// Builds edits_E.json from the plan below and checks thread coverage. node build_E.js
const fs = require('fs'), path = require('path');
const DIR = __dirname;
// ---- parse packet
const pk = fs.readFileSync(path.join(DIR, 'packet_E.md'), 'utf8').split(/\r?\n/);
const own = {}; let cur = null, who = null;
for (const l of pk) {
  const h = /^### (H|M) @(\S+)/.exec(l); if (h) { who = h[1]; cur = h[2]; own[cur] = { who, lines: [] }; continue; }
  const m = /^(\d+) \| (.*?) \| (.*)$/.exec(l); if (m && cur) own[cur].lines[+m[1]] = { uk: m[2].trim(), en: m[3].trim() };
}
// ---- plan: list -> entries [idx|null, mark, uk, en] ; [idx,'DEL']
const P = {};
function L(list, ...rows) { P[list] = (P[list] || []).concat(rows); }

