// ---- build edits
const edits = [], used = {};
for (const list in P) {
  const o = own[list]; if (!o) throw new Error('not owned list ' + list);
  for (const r of P[list]) {
    const [idx, mark, uk, en] = r;
    if (idx != null) { if (!o.lines[idx]) throw new Error(list + ' bad idx ' + idx); if (used[list + idx]) throw new Error('dup ' + list + idx); used[list + idx] = 1; }
    if (mark === 'DEL') { edits.push({ who: o.who, list, op: 'del', old: o.lines[idx].uk }); continue; }
    const U = mark + ' ' + uk, E = mark + ' ' + en;
    if (idx == null) edits.push({ who: o.who, list, op: 'add', uk: U, en: E });
    else edits.push({ who: o.who, list, op: 'set', old: o.lines[idx].uk, uk: U, en: E });
  }
}
for (const list in own) own[list].lines.forEach((x, i) => { if (!used[list + i]) console.log('UNHANDLED', list, i, x.uk); });
fs.writeFileSync(path.join(DIR, 'edits_E.json'), JSON.stringify(edits, null, 1));

// ---- checks
const scenes = {
  fish: ['м_риба', 'х_риба', 'м_риба_кінець'], chop: ['х_рубка', 'м_рубка', 'х_рубка_кінець'], mine: ['м_руда', 'х_руда', 'м_руда_кінець'],
  raid: ['хд_набіг', 'мд_набіг', 'хд_набіг_кінець'], trade: ['мд_торг', 'хд_торг', 'мд_торг_кінець'], ride: ['хд_їзда', 'мд_їзда', 'хд_їзда_кінець'],
  smelt: ['мд_піч', 'хд_піч', 'мд_піч_кінець'], ferment: ['мд_бочка', 'хд_бочка', 'мд_бочка_кінець'], repair: ['хд_лагодження', 'мд_лагодження', 'хд_лагодження_кінець'] };
const parse = r => { const m = /^(?:~(\d+) )?\^(\S+) (.*)$/.exec(r[1] + ' ' + r[2]); const tone = m[1] || '123'; const [a, nx] = m[2].split('>'); return { tone, ans: a.split('|'), next: nx, text: m[3] }; };
const SW = /(бля|сук|суц|хуй|хуя|хує|пизд|курв|\{м_слівце\}|срак|срац|срат|сран|срал|гівн|падл|йоб|обісру)/gi;
let bad = 0;
for (const sc in scenes) {
  const [a, b, c] = scenes[sc].map(l => P[l].filter(r => r[1] !== 'DEL').map(parse));
  for (const st of [a, b, c]) for (const l of st) for (const t of l.ans.concat(l.next ? [l.next] : [])) if (!t.startsWith(sc + '.')) { console.log('PREFIX', sc, t); bad++; }
  const opens = [...new Set(a.map(l => l.ans[0]))];
  for (const T of opens) for (const tier of '123') {
    const rep = b.filter(l => l.tone.includes(tier) && l.ans.includes(T));
    if (rep.length < 2) { console.log('FEW REPLIES', sc, T, 'tier', tier, rep.length); bad++; }
  }
  const nexts = [...new Set(b.map(l => l.next || l.ans[0]))];
  for (const N of nexts) for (const tier of '123') {
    const cl = c.filter(l => l.tone.includes(tier) && l.ans.includes(N));
    if (cl.length < 2) { console.log('FEW CLOSES', sc, N, 'tier', tier, cl.length); bad++; }
  }
  for (const l of b) if (!opens.includes(l.ans[0])) { console.log('ORPHAN REPLY', sc, l.ans); bad++; }
  for (const l of c) for (const t of l.ans) if (!nexts.includes(t)) { console.log('ORPHAN CLOSE', sc, t); bad++; }
}
for (const list in P) if (list.startsWith('м')) for (const r of P[list]) { if (r[1] === 'DEL') continue; const n = (r[2].match(SW) || []).length;
  const pre = ['м_риба','м_руда','мд_торг','мд_піч','мд_бочка','м_рубка','мд_набіг','мд_їзда','мд_лагодження'].includes(list);
  if (n > 2 || (pre && n > 1)) { console.log('SWEARS', n, list, r[2]); bad++; } }
console.log('edits', edits.length, 'set', edits.filter(e => e.op === 'set').length, 'del', edits.filter(e => e.op === 'del').length, 'add', edits.filter(e => e.op === 'add').length, 'problems', bad);
